import{_ as e,o,c as t,a4 as a}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"机制七：会话持久化（src/session.ts）","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/mechanisms/session.md","filePath":"agent-cli/mechanisms/session.md"}'),n={name:"agent-cli/mechanisms/session.md"};function d(i,s,c,r,l,p){return o(),t("div",null,[...s[0]||(s[0]=[a(`<h1 id="机制七-会话持久化-src-session-ts" tabindex="-1">机制七：会话持久化（<code>src/session.ts</code>） <a class="header-anchor" href="#机制七-会话持久化-src-session-ts" aria-label="Permalink to &quot;机制七：会话持久化（\`src/session.ts\`）&quot;">​</a></h1><blockquote><p>会话 = 一份 JSON 消息数组。这个模块看似简单，但&quot;隔离 / 锁 / 图片 / 不存 system prompt&quot;四个决定都不平凡。</p></blockquote><h2 id="_1-磁盘布局" tabindex="-1">1. 磁盘布局 <a class="header-anchor" href="#_1-磁盘布局" aria-label="Permalink to &quot;1. 磁盘布局&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.agent-cli/                       （AGENT_CLI_DIR 可整体覆盖）</span></span>
<span class="line"><span>└── session/</span></span>
<span class="line"><span>    └── &lt;workspace-id&gt;/             每个工作目录一个文件夹</span></span>
<span class="line"><span>        ├── session-&lt;unixms&gt;.json   会话消息（对话内容）</span></span>
<span class="line"><span>        └── session-&lt;unixms&gt;.lock   会话锁（记录持有进程 pid）</span></span></code></pre></div><ul><li><code>&lt;workspace-id&gt;</code> = <strong>cwd 的 sha256 前 16 位</strong> → 不同目录启动的会话互不干扰。</li><li><code>-r</code> / <code>/resume</code>：<code>listSessions()</code> 列出当前 workspace 的会话（时间 + 消息数 + 锁状态）。</li></ul><h2 id="_2-关键设计决定" tabindex="-1">2. 关键设计决定 <a class="header-anchor" href="#_2-关键设计决定" aria-label="Permalink to &quot;2. 关键设计决定&quot;">​</a></h2><ol><li><strong>会话 id 只在内存</strong>：不落盘&quot;当前会话&quot;指针 → 没有退出清空 / 异常残留 / 多进程&quot;当前会话&quot;冲突问题。</li><li><strong>实时保存</strong>：每条用户消息、每次回答完成后立即写盘（<strong>不是退出时</strong>）—— 崩溃也不丢。</li><li><strong>不存 system prompt</strong>：只存 user / assistant / tool 消息。恢复时由 <code>index.ts</code> 用<strong>当前</strong>提示词重新组装 —— 避免提示词改版后旧会话带过期 system，也保护前缀稳定性。</li><li><strong>图片不内联 base64</strong>：写盘前 <code>stripImages</code> 把 <code>image_url</code> 换成自定义 <code>image_ref</code>（一张全屏截图可达数 MB，内联会让会话文件膨胀、<code>listSessions</code> 的 <code>JSON.parse</code> 变慢）；恢复时 <code>hydrateImages</code> 重读 <code>images/</code> 目录还原成 data URL，文件已失效则降级为文本标记。</li></ol><h2 id="_3-会话锁" tabindex="-1">3. 会话锁 <a class="header-anchor" href="#_3-会话锁" aria-label="Permalink to &quot;3. 会话锁&quot;">​</a></h2><ul><li><strong>编辑会话前</strong> <code>acquireSessionLock(id)</code>；正常退出 <code>releaseSessionLock(id)</code>。</li><li><strong>异常退出残留的锁</strong>：锁文件里记录持有进程 pid → 下次用 <strong>pid 存活探测</strong>判定过期并自动接管（不要求用户手删）。</li><li>锁被他人持有时：<code>-r</code> 列表标 <code>[locked]</code> 且不可选；直接恢复给出明确提示。</li></ul><h2 id="_4-配套的用户级文件" tabindex="-1">4. 配套的用户级文件 <a class="header-anchor" href="#_4-配套的用户级文件" aria-label="Permalink to &quot;4. 配套的用户级文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>~/.agent-cli/config.json</code></td><td>模型 / 思考等级 / <code>trustedProjects</code> / <code>trustedHooks</code>（<code>user-config.ts</code>；损坏返回 <code>{}</code>，写失败静默降级）</td></tr><tr><td><code>~/.agent-cli/prompt.md</code></td><td>用户自定义根提示词（存在则<strong>替换</strong>内置默认值）</td></tr><tr><td><code>~/.agent-cli/memory/memory.md</code></td><td>用户长期记忆（启动时拼进 system prompt 的<strong>消息尾部</strong>，不改前缀）</td></tr></tbody></table><h2 id="_5-测试" tabindex="-1">5. 测试 <a class="header-anchor" href="#_5-测试" aria-label="Permalink to &quot;5. 测试&quot;">​</a></h2><p><code>session.test.ts</code>：workspace 隔离、锁的获取 / 释放 / pid 过期接管、strip/hydrate 图片往返、损坏文件容错。</p>`,13)])])}const m=e(n,[["render",d]]);export{g as __pageData,m as default};
